/* @autogenerated */
import { Component, computed, effect, inject, input, untracked } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { MAT_FORM_FIELD_DEFAULT_OPTIONS, MatFormFieldDefaultOptions } from '@angular/material/form-field';
import { AppStateService, ContextValue, GLOBAL_CONTEXT } from '@shared/context/state/app-state.service';
import { SelectorProvider } from '@shared/data/selector-provider';
import { EditableSelectoneComponent } from '@shared/toolkit/editable/editable-selectone/editable-selectone.component';

/** Qué hace el valor elegido: ver `ContextValue.fixed`, `ContextValue.filter` y `ContextValue.default`. */
export type ContextSelectorMode = 'fixed' | 'filter' | 'default';

/**
 * Selector de una entrada del contexto. Guarda lo elegido con su `entity` en el ámbito del workspace activo
 * (o en el global con `global`), y los repositorios lo aplican a sus campos. Mientras falte alguno de los
 * selectores de `requires` se ve deshabilitado, y en cuanto todos tienen valor se habilita; si cambia o se vacía
 * uno de ellos, lo elegido aquí se borra. Las opciones se buscan en el servidor al abrirlo o al escribir.
 * Es un campo compacto (sin hueco para ayudas ni errores) y sin valor muestra su placeholder ("Sin cliente").
 */
@Component({
  selector: 'context-selector',
  imports: [ReactiveFormsModule, EditableSelectoneComponent],
  template: `<editable-selectone [formControl]="control" [label]="label() ?? key()" [provider]="provider()" />`,
  styleUrl: './context-selector.component.scss',
  providers: [
    {
      provide: MAT_FORM_FIELD_DEFAULT_OPTIONS,
      // La etiqueta siempre arriba: así se ve el placeholder ("Sin cliente") mientras no hay valor
      useValue: {
        appearance: 'outline',
        subscriptSizing: 'dynamic',
        floatLabel: 'always',
      } satisfies MatFormFieldDefaultOptions,
    },
  ],
  host: { class: 'context-selector', '[class.context-selector-disabled]': '!enabled()' },
})
export class ContextSelectorComponent {
  key = input.required<string>();
  provider = input.required<SelectorProvider<any, any>>();
  /** Entidad que elige (`'client'`), en kebab-case como en el modelo. */
  entity = input<string>();
  label = input<string>();
  requires = input<string[]>([]);
  global = input<boolean>(false);
  mode = input<ContextSelectorMode>('fixed');

  readonly control = new FormControl<any>(null);
  private readonly appState = inject(AppStateService);

  /** Si se puede usar: todos los selectores de `requires` tienen valor. */
  readonly enabled = computed(() => {
    const contexts = this.appState.contexts();
    return this.requires().every((key) => present(contexts[key]?.value));
  });

  constructor() {
    // El control sigue al contexto (otra pestaña, un cambio de workspace…) sin volver a escribirlo
    effect(() => {
      const current = this.appState.contexts()[this.key()]?.value ?? null;
      const provider = this.provider();
      untracked(() => {
        this.control.setValue(current, { emitEvent: false });
        // El valor del FormControl no actualiza por sí solo el texto que muestra el autocomplete.
        // Sincronizar el provider también limpia/recupera su selección cuando cambia el contexto padre.
        const selected = provider.selection();
        const selectedValue = selected ? provider.value(selected) : null;
        if (!sameReference(current, selectedValue)) {
          provider.select(current);
        }
      });
    });
    // Sin los selectores de los que depende se deshabilita; si cambia alguno, lo elegido deja de tener sentido
    let previous: { scope: string; parents: string } | undefined;
    effect(() => {
      const enabled = this.enabled();
      const scope = this.appState.contextScope();
      const contexts = this.appState.contexts();
      const parents = JSON.stringify(this.requires().map((key) => refOf(contexts[key]?.value)));
      // Al cambiar de workspace (o al crearse) solo se toma la referencia: no es un cambio del padre
      const parentChanged = !!previous && previous.scope === scope && previous.parents !== parents;
      previous = { scope, parents };
      untracked(() => {
        if (enabled && this.control.disabled) {
          this.control.enable();
        } else if (!enabled && this.control.enabled) {
          this.control.disable();
        }
        if ((!enabled || parentChanged) && present(contexts[this.key()]?.value)) {
          this.store(null);
        }
      });
    });
    this.control.valueChanges.pipe(takeUntilDestroyed()).subscribe((value) => this.store(value));
  }

  private store(value: unknown): void {
    const key = this.key();
    const entry = present(value) ? ContextValue[this.mode()](key, value, this.entity()) : null;
    this.appState.setContext(key, entry, this.global() ? GLOBAL_CONTEXT : undefined);
  }
}

function present(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '';
}

/** Clave de un valor de referencia (`{ $ref }`) o el valor tal cual: para comparar sin depender de otros campos. */
function refOf(value: unknown): unknown {
  return value && typeof value === 'object' && '$ref' in value ? (value as { $ref: unknown }).$ref : (value ?? null);
}

function sameReference(one: unknown, other: unknown): boolean {
  return refOf(one) === refOf(other);
}
